// The extension re-implements the Python scoring engine in JS. A silent
// divergence between the two would mean the badge on the page disagrees with
// the CLI -- so these assert against numbers generated by the Python side
// (extension/test/python-reference.json, regenerated from the same fixtures).

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";

import {
  scoreListing, estimateReserve, powertrainWarranty, roughValue,
  worthOpening, detectFormat, planAcquisition,
} from "../src/scoring.js";

const REF = JSON.parse(readFileSync(new URL("./python-reference.json", import.meta.url)));

const CFG = {
  buyBox: {
    targetGross: 1200, targetGrossPct: 0.06, minGrade: 0, maxOdometer: 160000,
    minWholesaleValue: 0, maxWholesaleValue: 1e9, maxRecon: 6000,
    allowInoperable: true, allowAsIsInop: true, maxPowertrainReserve: 25000,
    maxRiskSpread: 3000, allowedMakes: [], excludedMakes: [],
  },
  costs: {
    buyFee: 400, transportPerMile: 1.15, transportMinimum: 150,
    defaultTransportMiles: 250, floorplanDaily: 9,
    baselineRecon: 450, reconSafetyMultiplier: 1.25,
  },
  capabilities: { evBatteryPack: 3500, evDriveUnit: 3500, unpricedPowertrainMinGross: 4000 },
  exits: [
    { name: "wholesale", daysHeld: 21, sellFee: 300, reconMultiplier: 1.0, targetGross: 1200, targetGrossPct: 0.06 },
    { name: "retail", daysHeld: 45, sellFee: 0, reconMultiplier: 1.6, targetGross: 2500, targetGrossPct: 0.10 },
  ],
};

const TESLA = {
  vin: "5YJYGDEF2MF252410", year: 2021, make: "Tesla", model: "Model Y",
  trim: "Performance", odometer: 143991, grade: 3.1, currentBid: 11500,
  saleFormat: "timed", drivable: false, asIs: true,
  announcements: ["AS-IS", "INOP", "Refer to CR for Disclosures"],
  mechanical: "Not Drivable - INOP",
  conditionReport: "Not Drivable - Mechanical, Unverified Items.",
};
const TESLA_VAL = {
  source: "accutrade", wholesale: 15750, mmr: 15750, retail: 21179,
  adjustedForMileage: true, adjustedForCondition: false,
};

const JETTA = {
  vin: "3VW6T7BU3LM012345", year: 2020, make: "Volkswagen", model: "Jetta",
  trim: "GLI", odometer: 43700, grade: 4.3, reserve: 10400,
  makeOffer: true, saleFormat: "make_offer", announcements: [],
};
const JETTA_VAL = {
  source: "accutrade", wholesale: 13610, mmr: 13610, retail: 17200,
  adjustedForMileage: true, adjustedForCondition: false,
};

function near(actual, expected, label, tol = 0.01) {
  assert.ok(Math.abs(actual - expected) <= tol,
    `${label}: JS ${actual} vs Python ${expected}`);
}

test("Tesla scores identically to the Python engine", () => {
  const ref = REF["Model Y"];
  const d = scoreListing(TESLA, TESLA_VAL, CFG);
  near(d.maxBid, ref.maxBid, "maxBid");
  near(d.maxBidOptimistic, ref.maxBidOptimistic, "maxBidOptimistic");
  near(d.headroom, ref.headroom, "headroom");
  near(d.powertrainReserve.high, ref.reserveHigh, "reserveHigh");
  near(d.powertrainReserve.low, ref.reserveLow, "reserveLow");
  near(d.score, ref.score, "score", 0.001);
  assert.equal(d.exitChannel, ref.exitChannel);
  assert.equal(d.acquisition.format, ref.format);
  assert.equal(d.acquisition.certainty, ref.certainty);
  assert.equal(d.speculative, ref.speculative);
});

test("Jetta make-offer scores identically to the Python engine", () => {
  const ref = REF["Jetta"];
  const d = scoreListing(JETTA, JETTA_VAL, CFG);
  near(d.maxBid, ref.maxBid, "maxBid");
  near(d.headroom, ref.headroom, "headroom");
  near(d.score, ref.score, "score", 0.001);
  assert.equal(d.exitChannel, ref.exitChannel);
  assert.equal(d.acquisition.certainty, ref.certainty);
  assert.equal(d.acquisition.format, ref.format);
});

test("Tesla battery warranty is expired on mileage", () => {
  const [covered, why] = powertrainWarranty(TESLA);
  assert.equal(covered, false);
  assert.match(why, /120,000/);
  assert.match(why, /143,991/);
});

test("in-house pack cost replaces the market number", () => {
  const withCap = estimateReserve(TESLA, { evBatteryPack: 3500, evDriveUnit: 3500 });
  const without = estimateReserve(TESLA, {});
  assert.equal(withCap.high, 3500);
  assert.equal(without.high, 17000);
  assert.deepEqual(without.unpriced, ["traction pack", "drive unit"]);
});

test("a published reserve is a firm price", () => {
  const acq = planAcquisition(JETTA, 13059.5, 13610);
  assert.equal(acq.price, 10400);
  assert.equal(acq.certainty, 1.0);
  assert.match(acq.action, /takes it now/);
});

test("an undisclosed unmet reserve is not a price", () => {
  const acq = planAcquisition({ currentBid: 11500, announcements: [] }, 20000, 25000);
  assert.equal(acq.price, null);
  assert.equal(acq.executable, false);
  assert.equal(acq.certainty, 0.2);
});

test("absolute announcement overrides a timed label", () => {
  assert.equal(detectFormat({ saleFormat: "timed", announcements: ["ABSOLUTE - no reserve"] }), "absolute");
});

// --- tier-1 triage: the ACV no-VIN case ------------------------------------

test("triage works with no VIN at all", () => {
  const row = { year: 2021, make: "Ford", model: "F-150", odometer: 62400, currentBid: 18500 };
  assert.equal(row.vin, undefined);
  assert.ok(roughValue(row) > 20000);
  assert.equal(worthOpening(row, CFG), true);
});

test("triage rejects a car with no room without opening it", () => {
  const row = { year: 2019, make: "Nissan", model: "Altima", odometer: 118400, currentBid: 9800 };
  assert.equal(worthOpening(row, CFG), false);
});

test("triage respects the buy box before spending a page load", () => {
  const tooOld = { year: 2005, make: "Ford", model: "F-150", odometer: 60000, currentBid: 3000 };
  assert.equal(worthOpening(tooOld, { ...CFG, buyBox: { ...CFG.buyBox, minYear: 2015 } }), false);
  const tooManyMiles = { year: 2021, make: "Ford", model: "F-150", odometer: 220000, currentBid: 8000 };
  assert.equal(worthOpening(tooManyMiles, CFG), false);
});

test("triage opens a car when the price is not shown", () => {
  const noPrice = { year: 2021, make: "Toyota", model: "RAV4", odometer: 48200 };
  assert.equal(worthOpening(noPrice, CFG), true);
});
